mapper.select:
select a.id from user_loan_repayment_order a LEFT JOIN user_info b on a.user_id = b.id where order_status = 0
and account_type = 0
${params.dataScope}

select sum(order_amount) order_amount,a.currency_id,currency_name
from user_loan_repayment_order a
left join user_info b
on a.user_id = b.id
left join platform_currency c
on a.currency_id = c.id
left join loan_order d
on a.loan_order_id = d.id

    and a.order_status = 1 and c.`status` = 0
     and loan_order_id = #{loanOrderId}
     and a.user_id = #{userId}
     and user_account like concat('%',#{userAccount},'%') 
     and nick_name like concat('%',#{nickName},'%') 
     and account_type = #{accountType}
     and a.order_code like concat('%', #{orderCode}, '%')
     and d.order_code like concat('%', #{loanOrderCode}, '%')
     and order_amount = #{orderAmount}
     and a.order_status = #{orderStatus}
     and operator_name like concat('%', #{operatorName}, '%')
     and pay_channel_name like concat('%', #{payChannelName}, '%')
     and pay_channel_id = #{payChannelId}
     and a.currency_id = #{currencyId}
     and recharge_img = #{rechargeImg}
     and recharge_msg = #{rechargeMsg}
     and recharge_method = #{rechargeMethod}
     and sql_version = #{sqlVersion}

        and agent_id in (select user_id from agent_team_level_line where sup_user_id = #{agentId} union select #{agentId})


        and agent_id = #{agentId}


           and DATE_FORMAT(a.create_time, '%Y-%m-%d %H:%i:%s')>=  DATE_FORMAT(#{startTime}, '%Y-%m-%d %H:%i:%s')   

          and DATE_FORMAT(a.create_time, '%Y-%m-%d %H:%i:%s') <= DATE_FORMAT(#{endTime}, '%Y-%m-%d %H:%i:%s')    
    ${params.dataScope}

group by a.currency_id

